FUZZ_SET_ATTR_INT(v, "avail", new_avail);

// vi must be initialized/populated by headers (we approximate with configured attribute)
int vi_inited = FUZZ_GET_ATTR_INT(vi, "init");
int configured = FUZZ_GET_ATTR_INT(vi, "configured");
if (!vi_inited || !configured) { FUZZ_BAIL(); }
// Build a fuzzed packet; library interprets it according to codec setup
std::string pkt = FUZZ_PARAM_STR();
ogg_packet op; memset(&op, 0, sizeof(op));
op.packet = (unsigned char *)pkt.data();
op.bytes = (long)pkt.size();
op.b_o_s = (int)(*FUZZ_PARAM(unsigned int) & 1U);
op.e_o_s = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1U);
op.granulepos = (ogg_int64_t)(*FUZZ_PARAM(long long));
op.packetno = (ogg_int64_t)(*FUZZ_PARAM(long long));
long bs = vorbis_packet_blocksize(vi, &op);
(void)bs; // may be 0 or negative on invalid packet; fine

// v (actually vorbis_info*) must be initialized/configured by headers or encoder setup
vorbis_info *info = v; // rename for clarity
int vi_inited = FUZZ_GET_ATTR_INT(info, "init");
int configured = FUZZ_GET_ATTR_INT(info, "configured");
if (!vi_inited || !configured) { FUZZ_BAIL(); }
int flag = (int)(*FUZZ_PARAM(unsigned int) & 1U);
int rc = vorbis_synthesis_halfrate(info, flag);
(void)rc;
// No attribute change required here

// Query halfrate status on a configured vorbis_info
vorbis_info *info = v;
int vi_inited = FUZZ_GET_ATTR_INT(info, "init");
int configured = FUZZ_GET_ATTR_INT(info, "configured");
if (!vi_inited || !configured) { FUZZ_BAIL(); }
int enabled = vorbis_synthesis_halfrate_p(info);
(void)enabled;
